The following is the first main result of this paper.

%
%th2.1 #&#
\begin{theorem}[(Anti-concentration for suprema of separable Gaussian processes)]\label{thm2}
Let $X=(X_{t})_{t \in T}$ be a separable Gaussian process indexed by a
semimetric space $T$ such that $\Ep[ X_{t} ] = 0$ and $\Ep[ X^{2}_{t}
] = 1$ for all $t \in T$. Assume that $\sup_{t \in T} X_{t} < \infty$
a.s. Then $a(X):= \Ep[ \sup_{t \in T} X_{t}] \in[0,\infty)$ and
%
%
%e7 #&#
\begin{equation}
p_{\epsilon} (X) \leq4 \epsilon \bigl(a(X) + 1 \bigr), \label
{eqanti-concentrationmain}
\end{equation}
%
for all $\epsilon\geq0$.
\end{theorem}

The similar conclusion holds for the concentration function of $\sup_{t \in T} |X_{t}|$.

%co2.1 #&#
\begin{corollary}\label{cor1}
Let $X=(X_{t})_{t \in T}$ be a separable Gaussian process indexed by a
semimetric space $T$ such that $\Ep[ X_{t} ] = 0$ and $\Ep[ X^{2}_{t}
] = 1$ for all $t \in T$. Assume that $\sup_{t \in T} X_{t} < \infty$
a.s. Then $a(|X|):= \Ep[ \sup_{t \in T} |X_{t}|] \in[\sqrt{2/\pi
},\infty)$ and
%
%
%e8 #&#
\begin{equation}
p_{\epsilon} \bigl(|X|\bigr) \leq4\epsilon\bigl(a\bigl(|X|\bigr) + 1\bigr), \label
{eqanti-concentrationmaincor}
\end{equation}
%
